/* Opt-in native UI/transport-state fixtures. Never loaded by normal play. */
static int mp_review_calls[MP_SAVE+1],mp_review_exclusive=1;
static int mp_review_transport(int a){
 mp_review_calls[a]++;
 if(a==MP_ON){mp_review_exclusive&=!wifi.state;online.enabled=1;online.retry=0;}
 if(a==MP_OFF){online.enabled=0;online_close(NULL);}
 if(a==MP_HOST||a==MP_JOIN){mp_review_exclusive&=!online.stage&&!online.enabled;wifi.state=a==MP_HOST?WIFI_CONNECT:WIFI_SCAN;wifi.host=a==MP_HOST;wifi.playing=a==MP_HOST;}
 if(a==MP_SEARCH){wifi.scan_done=0;wifi.rooms_n=0;wifi.scan_age=0;}
 if(a==MP_JOIN_ROOM)wifi.state=WIFI_CONNECT;
 return 1;
}
